package com.arceuusbuffoverlay;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ArceuusBuffOverlayPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(ArceuusBuffOverlayPlugin.class);
        RuneLite.main(args);
    }
}

package com.arceuusbuffoverlay;

enum TrackedSpell
{
    GREATER_CORRUPTION("Greater Corruption"),
    DEATH_CHARGE("Death Charge"),
    MARK_OF_DARKNESS("Mark of Darkness");

    private final String displayName;

    TrackedSpell(String displayName)
    {
        this.displayName = displayName;
    }

    String getDisplayName()
    {
        return displayName;
    }

    static TrackedSpell fromText(String text)
    {
        if (text == null)
        {
            return null;
        }

        String lower = stripTags(text).toLowerCase();

        for (TrackedSpell spell : values())
        {
            if (lower.contains(spell.displayName.toLowerCase()))
            {
                return spell;
            }
        }

        return null;
    }

    static String stripTags(String text)
    {
        if (text == null)
        {
            return "";
        }

        return text.replaceAll("<[^>]*>", "");
    }
}

package com.arceuusbuffoverlay;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class ArceuusBuffOverlay extends Overlay
{
    private static final Color MISSING_FILL = new Color(180, 0, 0, 75);
    private static final Color MISSING_BORDER = new Color(255, 40, 40, 210);
    private static final Color TIMER_FILL = new Color(0, 0, 0, 145);
    private static final Color TIMER_TEXT = Color.WHITE;
    private static final Color TIMER_SHADOW = Color.BLACK;
    private static final Color COOLDOWN_FILL = new Color(0, 25, 120, 95);
    private static final Color COOLDOWN_BORDER = new Color(40, 90, 255, 210);

    private final Client client;
    private final ArceuusBuffOverlayPlugin plugin;
    private final ArceuusBuffOverlayConfig config;

    @Inject
    ArceuusBuffOverlay(Client client, ArceuusBuffOverlayPlugin plugin, ArceuusBuffOverlayConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        boolean inCombat = plugin.isInCombat();

        if (!inCombat && !plugin.hasAnyActiveTimer())
        {
            return null;
        }

        Widget[] roots = client.getWidgetRoots();
        if (roots == null)
        {
            return null;
        }

        Set<Integer> renderedWidgetIds = new HashSet<>();
        for (Widget root : roots)
        {
            renderRecursive(graphics, root, renderedWidgetIds, inCombat);
        }

        return null;
    }

    private void renderRecursive(Graphics2D graphics, Widget widget, Set<Integer> renderedWidgetIds, boolean inCombat)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }

        if (!renderedWidgetIds.contains(widget.getId()))
        {
            TrackedSpell spell = findSpell(widget);
            if (spell != null)
            {
                Rectangle bounds = widget.getBounds();
                if (bounds != null && bounds.width > 5 && bounds.height > 5)
                {
                    renderSpell(graphics, bounds, spell, inCombat);
                    renderedWidgetIds.add(widget.getId());
                }
            }
        }

        renderChildren(graphics, widget.getStaticChildren(), renderedWidgetIds, inCombat);
        renderChildren(graphics, widget.getDynamicChildren(), renderedWidgetIds, inCombat);
        renderChildren(graphics, widget.getNestedChildren(), renderedWidgetIds, inCombat);
    }

    private void renderChildren(Graphics2D graphics, Widget[] children, Set<Integer> renderedWidgetIds, boolean inCombat)
    {
        if (children == null)
        {
            return;
        }

        for (Widget child : children)
        {
            renderRecursive(graphics, child, renderedWidgetIds, inCombat);
        }
    }

    private TrackedSpell findSpell(Widget widget)
    {
        if (!config.showOnlyOnSpellWidgets())
        {
            return null;
        }

        Rectangle bounds = widget.getBounds();
        if (bounds == null || !isInBottomRightPanel(bounds))
        {
            return null;
        }

        TrackedSpell byName = TrackedSpell.fromText(widget.getName());
        if (byName != null)
        {
            return byName;
        }

        return TrackedSpell.fromText(widget.getText());
    }

    private boolean isInBottomRightPanel(Rectangle bounds)
    {
        Dimension realDimensions = client.getRealDimensions();
        if (realDimensions == null)
        {
            return false;
        }

        // Widget bounds are based on the real client dimensions.
        // Stretched Mode can make the canvas larger, so using canvas width/height here
        // can incorrectly reject the spellbook widgets.
        int minX = realDimensions.width - 260;
        int minY = realDimensions.height - 360;

        return bounds.x >= minX && bounds.y >= minY;
    }

    private void renderSpell(Graphics2D graphics, Rectangle bounds, TrackedSpell spell, boolean inCombat)
    {
        if (plugin.shouldShowTimer(spell))
        {
            renderTimer(graphics, bounds, plugin.remainingSeconds(spell));
            return;
        }

        // Greater Corruption:
        // - On cooldown / cannot be cast: dark blue overlay
        // - Ready while in combat: red only if the setting is enabled
        if (spell == TrackedSpell.GREATER_CORRUPTION)
        {
            if (plugin.isOnCooldown(spell))
            {
                renderCooldown(graphics, bounds);
                return;
            }

            if (inCombat && config.highlightGreaterCorruptionReady())
            {
                renderMissing(graphics, bounds);
            }

            return;
        }

        // Death Charge / Mark of Darkness:
        // expired or not active while still in combat = red
        if (inCombat)
        {
            renderMissing(graphics, bounds);
        }
    }

    private void renderCooldown(Graphics2D graphics, Rectangle bounds)
    {
        graphics.setColor(COOLDOWN_FILL);
        graphics.fill(bounds);

        graphics.setColor(COOLDOWN_BORDER);
        graphics.setStroke(new BasicStroke(2));
        graphics.draw(bounds);
    }

    private void renderMissing(Graphics2D graphics, Rectangle bounds)
    {
        graphics.setColor(MISSING_FILL);
        graphics.fill(bounds);

        graphics.setColor(MISSING_BORDER);
        graphics.setStroke(new BasicStroke(2));
        graphics.draw(bounds);
    }

    private void renderTimer(Graphics2D graphics, Rectangle bounds, int seconds)
    {
        String text = seconds + "s";
        FontMetrics metrics = graphics.getFontMetrics();

        int paddingX = 3;
        int paddingY = 2;
        int textWidth = metrics.stringWidth(text);
        int textHeight = metrics.getAscent();

        int boxWidth = textWidth + paddingX * 2;
        int boxHeight = textHeight + paddingY * 2;
        int boxX = bounds.x + (bounds.width - boxWidth) / 2;
        int boxY = bounds.y + bounds.height - boxHeight - 2;

        graphics.setColor(TIMER_FILL);
        graphics.fillRoundRect(boxX, boxY, boxWidth, boxHeight, 6, 6);

        int textX = boxX + paddingX;
        int textY = boxY + paddingY + metrics.getAscent();

        graphics.setColor(TIMER_SHADOW);
        graphics.drawString(text, textX + 1, textY + 1);

        graphics.setColor(TIMER_TEXT);
        graphics.drawString(text, textX, textY);
    }
}

package com.arceuusbuffoverlay;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("arceuusbuffoverlay")
public interface ArceuusBuffOverlayConfig extends Config
{
    @Range(min = 1, max = 300)
    @ConfigItem(
        keyName = "greaterCorruptionSeconds",
        name = "Greater Corruption seconds",
        description = "Timer length for Greater Corruption. Default is 18 seconds."
    )
    default int greaterCorruptionSeconds()
    {
        return 18;
    }

    @Range(min = 1, max = 300)
    @ConfigItem(
        keyName = "deathChargeSeconds",
        name = "Death Charge seconds",
        description = "Timer length for Death Charge. Default is 60 seconds."
    )
    default int deathChargeSeconds()
    {
        return 60;
    }

    @Range(min = 1, max = 1800)
    @ConfigItem(
        keyName = "markOfDarknessSeconds",
        name = "Mark of Darkness seconds",
        description = "Timer length for Mark of Darkness without Purging staff. Default is 180 seconds."
    )
    default int markOfDarknessSeconds()
    {
        return 180;
    }

    @Range(min = 1, max = 10)
    @ConfigItem(
        keyName = "purgingStaffMultiplier",
        name = "Purging staff multiplier",
        description = "Multiplier applied to Mark of Darkness if Purging staff is equipped when cast."
    )
    default int purgingStaffMultiplier()
    {
        return 5;
    }

    @Range(min = 0, max = 20)
    @ConfigItem(
        keyName = "combatGraceTicks",
        name = "Combat grace ticks",
        description = "How many game ticks after interaction to keep showing combat overlays. Higher avoids flicker between attacks."
    )
    default int combatGraceTicks()
    {
        return 8;
    }

    @ConfigItem(
        keyName = "showOnlyOnSpellWidgets",
        name = "Only on spell widgets",
        description = "Only render on widgets whose text/name looks like the tracked spell names."
    )
    default boolean showOnlyOnSpellWidgets()
    {
        return true;
    }
    @ConfigItem(
        keyName = "highlightGreaterCorruptionReady",
        name = "Highlight Greater Corruption ready",
        description = "When enabled, Greater Corruption turns red in combat when it is ready to cast again. Default is off."
    )
    default boolean highlightGreaterCorruptionReady()
    {
        return false;
    }

}

package com.arceuusbuffoverlay;

import com.google.inject.Provides;
import java.util.EnumMap;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Arceuus Buff Overlay",
    description = "Shows Arceuus buff spell timers over the spellbook during combat.",
    tags = {"arceuus", "spellbook", "timer", "overlay", "death charge", "mark of darkness", "greater corruption"}
)
public class ArceuusBuffOverlayPlugin extends Plugin
{
    private static final double SECONDS_PER_TICK = 0.6;

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ArceuusBuffOverlay overlay;

    @Inject
    private ArceuusBuffOverlayConfig config;

    private final EnumMap<TrackedSpell, Integer> expirationTicks = new EnumMap<>(TrackedSpell.class);

    private int lastCombatTick = -1000;
    private TrackedSpell selectedTargetSpell;
    private int selectedTargetSpellTick = -1000;

    @Provides
    ArceuusBuffOverlayConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ArceuusBuffOverlayConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        expirationTicks.clear();
        selectedTargetSpell = null;
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        Player local = client.getLocalPlayer();
        if (local != null && isCombatDetected(local))
        {
            lastCombatTick = client.getTickCount();
        }

        // Drop stale selected-target spell state after 10 seconds.
        if (selectedTargetSpell != null && client.getTickCount() - selectedTargetSpellTick > secondsToTicks(10))
        {
            selectedTargetSpell = null;
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        String message = TrackedSpell.stripTags(event.getMessage()).toLowerCase();

        // If you try to cast Greater Corruption while it is still unavailable,
        // OSRS sends this message. Keep the spell blue instead of red.
        if (message.contains("can only cast corruption spells"))
        {
            if (!isOnCooldown(TrackedSpell.GREATER_CORRUPTION))
            {
                expirationTicks.put(
                    TrackedSpell.GREATER_CORRUPTION,
                    client.getTickCount() + secondsToTicks(3)
                );
            }
            return;
        }

        // Death Charge success message.
        // Do NOT start/reset on: "You can only cast Death Charge once every 60 seconds."
        if (message.contains("upon the death of your next foe"))
        {
            startTimer(TrackedSpell.DEATH_CHARGE);
            return;
        }

        // Mark of Darkness success message.
        if (message.contains("placed a mark of darkness"))
        {
            startTimer(TrackedSpell.MARK_OF_DARKNESS);
            return;
        }

        // Optional cleanup if the game sends a fade/expire message.
        if (message.contains("mark of darkness") && (message.contains("fades") || message.contains("faded") || message.contains("worn off")))
        {
            expirationTicks.remove(TrackedSpell.MARK_OF_DARKNESS);
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        String option = TrackedSpell.stripTags(event.getMenuOption());
        String target = TrackedSpell.stripTags(event.getMenuTarget());
        String combined = option + " " + target;

        TrackedSpell clickedSpell = TrackedSpell.fromText(combined);
        MenuAction action = event.getMenuAction();

        if (clickedSpell == TrackedSpell.GREATER_CORRUPTION)
        {
            // Greater Corruption is target-based. First click usually selects the spell;
            // the second click on NPC/player actually uses it.
            selectedTargetSpell = TrackedSpell.GREATER_CORRUPTION;
            selectedTargetSpellTick = client.getTickCount();

            if (isTargetAction(action))
            {
                if (!isOnCooldown(TrackedSpell.GREATER_CORRUPTION))
                {
                    startTimer(TrackedSpell.GREATER_CORRUPTION);
                }
                selectedTargetSpell = null;
            }

            return;
        }

        if (clickedSpell == TrackedSpell.DEATH_CHARGE || clickedSpell == TrackedSpell.MARK_OF_DARKNESS)
        {
            // Do not start these timers on click.
            // Wait for the real in-game success chat message instead.
            return;
        }

        if (selectedTargetSpell != null && isTargetAction(action))
        {
            if (!isOnCooldown(selectedTargetSpell))
            {
                startTimer(selectedTargetSpell);
            }
            selectedTargetSpell = null;
        }
    }

    private boolean isCombatDetected(Player local)
    {
        if (local.getInteracting() != null)
        {
            return true;
        }

        // Some combat situations drop your local interacting target between attacks.
        // This catches mobs that are still targeting you, so expired Death Charge /
        // Mark of Darkness can turn red while you are still on the same fight.
        for (NPC npc : client.getNpcs())
        {
            if (npc != null && npc.getInteracting() == local)
            {
                return true;
            }
        }

        return false;
    }

    boolean isInCombat()
    {
        return client.getGameState() == GameState.LOGGED_IN
            && client.getTickCount() - lastCombatTick <= config.combatGraceTicks();
    }

    boolean isActive(TrackedSpell spell)
    {
        Integer expires = expirationTicks.get(spell);
        return expires != null && expires > client.getTickCount();
    }

    boolean isOnCooldown(TrackedSpell spell)
    {
        Integer expires = expirationTicks.get(spell);
        return expires != null && expires > client.getTickCount();
    }

    boolean shouldShowTimer(TrackedSpell spell)
    {
        // Greater Corruption should NOT show a countdown.
        // Its timer is treated as cooldown-only.
        if (spell == TrackedSpell.GREATER_CORRUPTION)
        {
            return false;
        }

        return isActive(spell);
    }

    boolean hasAnyActiveTimer()
    {
        for (TrackedSpell spell : TrackedSpell.values())
        {
            if (shouldShowTimer(spell))
            {
                return true;
            }
        }

        return false;
    }

    int remainingSeconds(TrackedSpell spell)
    {
        Integer expires = expirationTicks.get(spell);
        if (expires == null)
        {
            return 0;
        }

        int remainingTicks = expires - client.getTickCount();
        if (remainingTicks <= 0)
        {
            return 0;
        }

        return (int) Math.ceil(remainingTicks * SECONDS_PER_TICK);
    }

    private void startTimer(TrackedSpell spell)
    {
        int seconds = getSpellDurationSeconds(spell);
        expirationTicks.put(spell, client.getTickCount() + secondsToTicks(seconds));
    }

    private int getSpellDurationSeconds(TrackedSpell spell)
    {
        switch (spell)
        {
            case GREATER_CORRUPTION:
                // OSRS corruption spell cooldown is 30 seconds.
                // Use max() so old saved config values like 18 do not make it turn red too early.
                return Math.max(30, config.greaterCorruptionSeconds());

            case DEATH_CHARGE:
                return config.deathChargeSeconds();

            case MARK_OF_DARKNESS:
                int seconds = config.markOfDarknessSeconds();
                if (isPurgingStaffEquipped())
                {
                    seconds *= config.purgingStaffMultiplier();
                }
                return seconds;

            default:
                return 1;
        }
    }

    private int secondsToTicks(int seconds)
    {
        return (int) Math.ceil(seconds / SECONDS_PER_TICK);
    }

    private boolean isTargetAction(MenuAction action)
    {
        return action == MenuAction.WIDGET_TARGET_ON_NPC
            || action == MenuAction.WIDGET_TARGET_ON_PLAYER
            || action == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT
            || action == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM
            || action == MenuAction.WIDGET_TARGET_ON_WIDGET;
    }

    private boolean isPurgingStaffEquipped()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        if (equipment == null)
        {
            return false;
        }

        Item[] items = equipment.getItems();
        int weaponSlot = EquipmentInventorySlot.WEAPON.getSlotIdx();

        return items.length > weaponSlot
            && items[weaponSlot] != null
            && items[weaponSlot].getId() == ItemID.PURGING_STAFF;
    }
}
